<?php

namespace Bga\Games\RegroupChickenArmy\States;

use Bga\Games\RegroupChickenArmy\Game;
use BgaUserException;
use Bga\Games\RegroupChickenArmy\Components\Market;
use BgaVisibleSystemException;

class PlayerTurnStateHandler implements StateHandlerInterface
{
    /* AUTOGENERATED_HANDLE_START - DO NOT REMOVE THIS COMMENT */
    public static function handle(Game $game, string $action, ...$args): void
    {
        switch ($action) {
            case 'pickDeckCard':
                self::pickDeckCard($game);
                break;
            case 'putCard':
                self::putCard($game, $args[0], $args[1], $args[2], $args[3]);
                break;
            default:
                throw new BgaVisibleSystemException("Invalid action: $action");
        }
    }
    /* AUTOGENERATED_HANDLE_END - DO NOT REMOVE THIS COMMENT */

    /* AUTOGENERATED_METHOD - putCard */
    private static function putCard(Game $game, int $cardId, int $rotation, int $posX, int $posY): void
    {
        // Add your action logic here
    }

    /* AUTOGENERATED_METHOD - pickDeckCard */
    private static function pickDeckCard(Game $game): void
    {
        $playerId = (int) $game->getCurrentPlayerId();

        $hasAlreadyPickADeckCard = $game->getUniqueValueFromDB(
            "SELECT `marketCardPicked` FROM `player` WHERE `player_id` = $playerId"
        );

        if ($hasAlreadyPickADeckCard != null) {
            $game->gamestate->nextState('retry');
            throw new BgaUserException(clienttranslate("You alreay had picked a deck card!"));
        }
        $deckCardId = Market::getMarketCard($game, 3);

        $game->DbQuery("UPDATE player SET marketCardPicked = $deckCardId WHERE player_id = $playerId");

        $game->notifyAllPlayers('deckCardPicked', clienttranslate('${player_name} picked a card from the deck.'), [
            'player_name' => $game->getActivePlayerName(),
            'player_id' => $playerId,
            'card_id' => $deckCardId
        ]);

        $game->gamestate->nextState("deckCardPicked");
    }

    public static function executeGameState(Game $game): void
    {
        // Add your state logic here
    }
}
